    /** Simple {@link JsonSchema} implementation that records calls to {@code preloadJsonSchema}. */
    private static class SimpleJsonSchema extends JsonSchema {
        private int preloadCount = 0;

        SimpleJsonSchema() {
            super(null, null, null, null);
        }

        @Override
        public void preloadJsonSchema() {
            preloadCount++;
        }

        int getPreloadCount() {
            return preloadCount;
        }

        /* --------------------------------------------------------------------- */
        /* The remaining abstract methods are not needed for the current tests. */
        @Override public Set<ValidationMessage> validate(ExecutionContext ctx, JsonNode node, JsonNode rootNode, String at) { return Collections.emptySet(); }
        @Override public Set<ValidationMessage> walk(ExecutionContext ctx, JsonNode node, JsonNode rootNode, String at, boolean walkAll) { return Collections.emptySet(); }
        @Override public JsonNode getSchemaNode() { return null; }
        @Override public JsonValidator getValidator() { return null; }
        @Override public String getSchemaPath() { return null; }
        @Override public JsonSchema getParentSchema() { return null; }
        @Override public String getRef() { return null; }
        @Override public String getSchemaLocation() { return null; }
    }

    /** Minimal {@link SchemaValidatorsConfig} implementation used by the tests. */
